/bin/bash -c 'for pw in secret secret2 abc; do
  key=$(printf '"'%s' \""'$pw" | md5sum | awk '"'{print "'$1}'"')
  case \""'$pw" in
    secret) s=8d6ee845c809045e147e7397809abe1d ;;
    secret2) s=111b8db0f2c120474308d772936fff38 ;;
    abc) s=ad48c61e022750384fcb7cccf611865c ;;
  esac
  iv=$(perl -e '"'print pack(\"H*\", "'$ARGV[0])'"' \""'$s" | openssl enc -d -aes-128-ecb -nopad -nosalt -K "$key" 2>/dev/null | od -An -tx1 -v | tr -d '"' \\n')
  printf '%s %s\\n' \""'$pw" "$iv"
done'

